// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t, uint256 b, address actor) public {
        vm.assume(t > 0);
        vm.assume(actor != address(c) && actor != address(this));
        // choose a block number NOT divisible by 15 so no payout occurs,
        // isolating the timestamp-guard difference
        b = bound(b, 1, type(uint128).max);
        if (b % 15 == 0) { b += 1; }
        vm.roll(b);
        vm.warp(t);
        vm.deal(actor, 20 ether);

        // first call: succeeds in both versions
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // second call in the SAME timestamp: must revert in reference C
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // reference: second call reverted, so balance is exactly the first deposit
        // mutant: second call accepted, balance becomes 30 ether
        assertTrue(!ok2 && address(c).balance == 20 ether);
    }
}
